const parseAdditionalProperties = (
	jsonSchema: JsonSchema.Object,
	context: JsonSchemaParseContext
) => {
	if (!("additionalProperties" in jsonSchema)) return

	const properties =
		jsonSchema.properties ? Object.keys(jsonSchema.properties) : []
	const patternProperties = Object.keys(jsonSchema.patternProperties ?? {})

	const additionalPropertiesSchema = jsonSchema.additionalProperties
	if (additionalPropertiesSchema === true) return true
	if (additionalPropertiesSchema === false) return false

	const schemaDefinedKeys = rootSchema(
		[...properties]
			.map(key => ({ unit: key }))
			.concat(
				[...patternProperties].map(key => ({
					domain: "string",
					pattern: key
				})) as never
			)
	)

	const jsonSchemaObjectAdditionalPropertiesValidator = (
		data: object,
		ctx: Traversal
	) => {
		for (const key of Object.keys(data)) {
			if (schemaDefinedKeys.allows(key))
				// not an additional property, so don't validate here
				continue

			const additionalPropertyValidator = parseJsonSchema(
				additionalPropertiesSchema
				, context
			)

			const value = data[key as keyof typeof data]
			if (!additionalPropertyValidator.allows(value)) {
				ctx.reject({
					path: [key],
					expected: `${additionalPropertyValidator.description}, since ${key} is an additional property.`,
					actual: printable(value)
				})
			}
		}
		return !ctx.hasError()
	}
	return jsonSchemaObjectAdditionalPropertiesValidator
}

const parseDependencies = (
	jsonSchema: JsonSchema.Object,
	context: JsonSchemaParseContext
): Predicate.Schema[] => {
	const dependentRequired: Record<string, string[]> = {
		...(jsonSchema.dependentRequired ?? {})
	}
	const dependentSchemas: Record<string, JsonSchema> = {
		...(jsonSchema.dependentSchemas ?? {})
	}
	for (const [trigger, dependency] of Object.entries(jsonSchema.dependencies ?? {}))
		if (Array.isArray(dependency)) dependentRequired[trigger] = dependency
		else dependentSchemas[trigger] = dependency as JsonSchema

	const predicates: Predicate.Schema[] = []
	for (const [trigger, keys] of Object.entries(dependentRequired))
		predicates.push((data: object, ctx: Traversal) => {
			if (!Object.hasOwn(data, trigger)) return true
			for (const key of keys)
				if (!Object.hasOwn(data, key))
					return ctx.reject({
						path: [key],
						expected: `a required dependent property because ${trigger} is present`,
						actual: "missing"
					})
			return true
		})

	for (const [trigger, schema] of Object.entries(dependentSchemas)) {
		const validator = parseJsonSchema(schema, context)
		predicates.push((data: object, ctx: Traversal) =>
			!Object.hasOwn(data, trigger) || validator.allows(data) ?
				true
			: ctx.reject({
					expected: `${validator.description}, because ${trigger} is present`,
					actual: printable(data)
				})
		)
	}
	return predicates
}

