const parseRef = (ref: unknown, context: JsonSchemaParseContext): type.Any => {
	if (typeof ref !== "string" || !/^#\/\$defs\/[^/]+$/.test(ref))
		throwParseError(
			"Only local $ref values of the form #/$defs/<name> are supported"
		)
	const name = ref.slice("#/$defs/".length)
	const definition = context.defs[name]
	if (definition === undefined)
		throwParseError(
			`Unable to resolve $ref ${JSON.stringify(ref)} from root $defs`
